<script lang="ts">
  import { untrack } from 'svelte';
  import gsap from 'gsap';
  import { slide } from 'svelte/transition';
  import { IconCheck, IconChevronDown, IconSearch, IconMail, IconX } from '@tabler/icons-svelte';
  import { resolveFilament, colorsForMaterial } from '../lib/colorMatching';
  let {value=$bindable(),material='pla',finish=$bindable(''),standardColor=$bindable('')}:{value:string;material?:string;finish?:string;standardColor?:string}=$props();
  let query=$state(''),expanded=$state(false);
  let previous=untrack(()=>material);
  const palette=$derived(colorsForMaterial(material));
  const groups=$derived([...new Set(palette.map(c=>c.series))]);
  const preferred=$derived(groups.find(s=>s==='PLA Basic'||s==='PETG HF')??groups[0]??'');
  const activeSeries=$derived(groups.includes(finish)?finish:preferred);
  const primaryGroups=$derived(groups.filter(s=>material==='pla'?['PLA Basic','PLA Matte','PLA Silk'].includes(s):true).slice(0,3));
  const moreGroups=$derived(groups.filter(s=>!primaryGroups.includes(s)));
  const label=(group:string)=>group.replace(/^(PLA|PETG|ASA|TPU) /,'');
  const surfaceEffect=(group:string)=>/translucent|transparent/i.test(group)?'translucent':/marble/i.test(group)?'marble':/sparkle|galaxy/i.test(group)?'sparkle':/silk|metal/i.test(group)?'silk':/matte/i.test(group)?'matte':'basic';
  const description=(group:string)=>({matte:'Miękki, matowy efekt',silk:'Wyrazisty połysk',marble:'Mineralna faktura',sparkle:'Migoczące drobinki',basic:'Gładkie wykończenie',translucent:'Lekko przezroczysty'}[surfaceEffect(group)]);
  function selectFinish(group:string){finish=group;value='';standardColor='custom';query='';}
  function selectShade(id:string){value=id;finish=activeSeries;standardColor='custom';}
  const filtered=$derived(palette.filter(c=>c.series===activeSeries&&`${c.name} ${c.series} ${c.code}`.toLocaleLowerCase('pl').includes(query.toLocaleLowerCase('pl').trim())));
  const choice=$derived(standardColor==='custom'?resolveFilament(value):palette.find(c=>c.series===activeSeries&&c.name.toLowerCase()===({black:'black',white:'white',green:'bambu green'}[standardColor]??''))); 
  const swatch=(c:typeof palette[number])=>c.hexes.length>1?`linear-gradient(135deg,${c.hexes.join(',')})`:c.hex;
  const ease=gsap.parseEase('power3.out');
  const duration=()=>matchMedia('(prefers-reduced-motion:reduce)').matches||document.documentElement.dataset.input==='keyboard'?0:360;
  $effect(()=>{const current=material;untrack(()=>{if(current!==previous){query='';expanded=false;previous=current;}});});

</script>
<div class="radial-palette-panel filament-panel" data-effect={surfaceEffect(activeSeries)} transition:slide|global={{duration:duration(),easing:ease}}>
 <fieldset class="finish-field"><legend>Wykończenie <span>Najpierw wybierz efekt powierzchni</span></legend>
  <div class="finish-options">{#each primaryGroups as group}<label class="finish-option" class:selected={activeSeries===group}><input class="choice-input" type="radio" name="filament-finish" value={group} checked={activeSeries===group} onchange={()=>selectFinish(group)}/><span class="finish-orb" data-effect={surfaceEffect(group)} aria-hidden="true"></span><strong>{label(group)}</strong><small>{description(group)}</small><IconCheck size={14}/></label>{/each}</div>
  {#if moreGroups.length}<button class="more-finishes" class:selected={moreGroups.includes(activeSeries)} type="button" aria-expanded={expanded} onclick={()=>expanded=!expanded}><span class="finish-stack" aria-hidden="true"><i class="finish-orb" data-effect="marble"></i><i class="finish-orb" data-effect="sparkle"></i><i class="finish-orb" data-effect="silk"></i></span><span class="more-copy"><b>{expanded?'Zwiń wykończenia':`Zobacz ${moreGroups.length} innych wykończeń`}</b><small>{moreGroups.includes(activeSeries)?`Wybrano: ${label(activeSeries)}`:moreGroups.slice(0,3).map(label).join(' · ')+' i inne'}</small></span><IconChevronDown size={20}/></button>{#if expanded}<div class="extra-finishes">{#each moreGroups as group}<label class:selected={activeSeries===group}><input class="choice-input" type="radio" name="filament-finish" value={group} checked={activeSeries===group} onchange={()=>selectFinish(group)}/><span class="mini-orb finish-orb" data-effect={surfaceEffect(group)}></span><span>{label(group)}</span>{#if activeSeries===group}<IconCheck size={13}/>{/if}</label>{/each}</div>{/if}{/if}
 </fieldset>
 <div class="palette-toolbar"><strong>Kolory · {label(activeSeries)}</strong><span>Bambu Lab</span></div>
 <label class="palette-search"><IconSearch size={16}/><input aria-label="Szukaj koloru Bambu Lab" placeholder="Nazwa lub kod koloru…" bind:value={query}/>{#if query}<button type="button" aria-label="Wyczyść wyszukiwanie kolorów" onclick={()=>{query='';}}><IconX size={15}/></button>{/if}</label>
 <div class="palette-count"><span>{activeSeries}</span><span>{filtered.length} kolorów</span></div>
 {#if !filtered.length}<div class="no-colors"><strong>Nie znaleziono koloru</strong><button type="button" onclick={()=>{query='';}}>Wyczyść wyszukiwanie</button></div>
 {:else}
  <fieldset class="sample-field"><legend class="sr-only">Wybierz kolor Bambu Lab z próbek</legend><div class="sample-tray">{#each filtered as shade}<label class="filament-sample" class:selected={choice?.id===shade.id}><input class="choice-input" type="radio" name="custom-shade-tray" value={shade.id} checked={choice?.id===shade.id} onchange={()=>selectShade(shade.id)} aria-label={`${shade.name}, ${shade.series}, kod ${shade.code}`}/><span class="tray-swatch" style:background={swatch(shade)} data-effect={surfaceEffect(shade.series)}><IconCheck size={15}/></span><strong>{shade.name}</strong></label>{/each}</div></fieldset>
 {/if}
 {#if choice}<div class="selected-filament" aria-live="polite"><span class="selected-swatch" style:background={swatch(choice)}></span><div><strong>{choice.name}</strong><small>Bambu Lab {choice.series} · kod {choice.code}</small>{#if choice.hexes.length>1}<small>Wielobarwny · podgląd modelu jest orientacyjny</small>{/if}</div></div>{/if}
 <p class="palette-note"><IconMail size={16}/><span>Wybrany filament i dostępność potwierdzimy przez e-mail. Kolor na ekranie jest orientacyjny.</span></p>
</div>
<style>
 .filament-panel{padding:18px 0 0;min-width:0}.palette-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:14px}.palette-toolbar>strong{font:600 16px var(--display)}.palette-toolbar>span{color:var(--muted);font-size:11px}
 .finish-field{padding:0 0 20px;margin:0 0 20px!important;border:0;border-bottom:1px solid var(--line);min-width:0}.finish-field legend{display:flex;justify-content:space-between;gap:10px;width:100%;font-size:13px;font-weight:700;margin-bottom:10px}.finish-field legend span{font-size:10px;font-weight:400;color:var(--muted)}.finish-options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.finish-option{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;padding:11px 5px 10px;border:1px solid var(--control-line);cursor:pointer;gap:5px;min-width:0}.finish-option.selected{border-color:var(--accent);background:var(--soft);box-shadow:inset 0 -2px var(--accent)}.finish-option>strong{font:650 15px var(--display)}.finish-option>small{font-size:10px;color:var(--muted);line-height:1.4;min-height:14px}.finish-option :global(svg){position:absolute;right:7px;top:7px;color:var(--accent);opacity:0}.finish-option.selected :global(svg){opacity:1}.finish-option:has(:focus-visible),.extra-finishes label:has(:focus-visible){outline:2px solid var(--accent);outline-offset:3px}.finish-orb{display:block;width:32px;height:32px;border-radius:50%;background:radial-gradient(circle at 32% 25%,#b7c4b1,#5f7258 48%,#253023 85%);box-shadow:inset -3px -4px 9px #0005}.finish-orb[data-effect=translucent]{background:radial-gradient(circle at 30% 25%,#ecffddaa,#a4c08d33 40%,#8aaf6933 65%,#d3edb088 95%);border:1px solid #dae8ce77;box-shadow:inset 0 0 13px #e0f4cf44,inset -5px -4px 7px #050d0722}.finish-orb[data-effect=matte]{background:radial-gradient(circle at 36% 30%,#98a58f,#74846c 60%,#53604d);box-shadow:inset -2px -3px 12px #0002}.finish-orb[data-effect=silk]{background:linear-gradient(120deg,#283522 5%,#82956a 25%,#eef8cc 34%,#8b9d72 42%,#394a2c 60%,#c9dc9a 78%,#52653f 93%)}.finish-orb[data-effect=marble]{background:radial-gradient(ellipse at 18% 28%,#343c32aa 0 .8px,transparent 1.3px) 0 0/9px 11px,radial-gradient(ellipse at 72% 63%,#343c3299 0 .7px,transparent 1.2px) 0 0/13px 9px,radial-gradient(circle at 30% 25%,#e1e1d4,#8d9685)}.finish-orb[data-effect=sparkle]{background:radial-gradient(circle,#ecf8c5 0 1px,transparent 1.7px) 0 0/9px 11px,radial-gradient(circle,#c6de8f 0 1px,transparent 1.6px) 4px 6px/13px 17px,radial-gradient(circle at 30% 25%,#6c8051,#26321d)}.more-finishes{display:flex;align-items:center;gap:15px;width:100%;min-height:72px;margin-top:10px;border:1px solid var(--control-line);background:transparent;color:var(--ink);padding:13px 15px;font-size:14px;font-weight:650;text-align:left;cursor:pointer}.more-finishes.selected{border-color:var(--accent);background:var(--soft);box-shadow:inset 0 -2px var(--accent)}.finish-stack{display:flex;align-items:center;flex-shrink:0;padding-right:0}.finish-stack .finish-orb{width:29px;height:29px;border:2px solid var(--surface);margin-left:-12px}.finish-stack .finish-orb:first-child{margin-left:0}.more-copy{display:flex;flex-direction:column;gap:6px;min-width:0}.more-copy b{font:650 15px var(--display);line-height:1.3;color:var(--ink)}.more-copy small{font-size:11px;font-weight:400;line-height:1.4;color:var(--muted)}.more-finishes :global(svg){margin-left:auto;flex-shrink:0;color:var(--accent);transition:transform 180ms}.more-finishes[aria-expanded=true] :global(svg){transform:rotate(180deg)}.more-finishes:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.extra-finishes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:12px}.extra-finishes label{position:relative;display:flex;align-items:center;gap:8px;border:1px solid var(--line);padding:9px;cursor:pointer;font-size:11px}.extra-finishes label.selected{border-color:var(--accent);color:var(--accent)}.extra-finishes :global(svg){margin-left:auto;flex-shrink:0}.mini-orb{width:24px;height:24px;flex-shrink:0}
 .palette-search{display:flex;align-items:center;gap:8px;padding:0 10px;border:1px solid var(--control-line);border-radius:3px;color:var(--muted)}.palette-search input{border:0;background:none;color:var(--ink);width:100%;min-width:0;padding:10px 0;font-size:12px}.palette-search button{border:0;padding:5px;background:none;color:var(--muted);cursor:pointer}.palette-count{display:flex;justify-content:space-between;gap:10px;font-size:10px;color:var(--muted);margin:12px 0 2px}
 .sample-field{border:0;padding:0;margin:12px 0 16px!important;min-width:0}.sample-tray{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;max-height:354px;overflow-y:auto;overscroll-behavior:contain;padding:3px 9px 3px 3px;scrollbar-width:thin;scrollbar-color:var(--control-line) transparent;scroll-padding-block:8px}.filament-sample{position:relative;display:flex;flex-direction:column;gap:7px;min-width:0;padding:5px 5px 8px;border:1px solid var(--line);cursor:pointer;border-radius:var(--control-radius);text-align:left;background:var(--surface);transition:border-color 160ms,background 160ms}.filament-sample.selected{background:var(--soft);border-color:var(--accent);box-shadow:inset 0 -2px var(--accent)}.tray-swatch{position:relative;width:100%;height:40px;border-radius:2px;border:1px solid #ffffff20;display:block;flex-shrink:0;overflow:hidden}.tray-swatch::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,#fff2,transparent 65%);pointer-events:none}.tray-swatch[data-effect=silk]::before{background:linear-gradient(115deg,transparent 10%,#fff1 25%,#fffb 39%,transparent 54%,#fff6 80%,transparent)}.tray-swatch[data-effect=matte]::before{background:#ffffff08}.tray-swatch[data-effect=marble]::before{background:radial-gradient(ellipse at 18% 28%,#26302399 0 .8px,transparent 1.3px) 0 0/11px 13px,radial-gradient(ellipse at 72% 63%,#26302377 0 .6px,transparent 1.1px) 0 0/17px 11px}.tray-swatch[data-effect=sparkle]::before{background:radial-gradient(circle,#fff9 0 1px,transparent 1.5px) 0 0/11px 13px}.tray-swatch :global(svg){position:absolute;right:3px;bottom:3px;opacity:0;background:var(--accent);color:var(--on-accent);border-radius:50%;padding:2px;box-sizing:content-box}.selected .tray-swatch :global(svg){opacity:1}.filament-sample strong{font-size:10px;line-height:1.4;font-weight:600;overflow-wrap:anywhere;min-height:28px}.filament-sample:has(input:focus-visible){outline:2px solid var(--accent);outline-offset:1px}
 .selected-filament{display:flex;align-items:center;gap:10px;padding:14px 0;border-top:1px solid var(--line)}.selected-swatch{width:32px;height:32px;border-radius:50%;border:1px solid var(--control-line);flex-shrink:0}.selected-filament strong{font-size:13px}.selected-filament small{display:block;font-size:10px;color:var(--muted);margin-top:4px}.palette-note{display:flex;gap:8px;align-items:flex-start;border-top:1px solid var(--line);padding:12px 0;color:var(--muted);font-size:10px;line-height:1.6}.palette-note :global(svg){flex-shrink:0;color:var(--accent);margin-top:1px}.no-colors{padding:30px 0;text-align:center;font-size:12px}.no-colors button{display:block;margin:12px auto 0;color:var(--accent);background:none;border:0;text-decoration:underline;cursor:pointer}
 @media(hover:hover) and (pointer:fine){.filament-sample:hover{background:var(--soft)}.more-finishes:hover{border-color:var(--accent);background:var(--soft)}}
 @media(max-width:420px){.sample-tray{grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}.palette-toolbar>strong{font-size:15px}.finish-field legend span{max-width:140px;text-align:right}.finish-option>small{min-height:28px}.tray-swatch{height:34px}}
 @media(prefers-reduced-motion:reduce){.filament-sample{transition:none}}
</style>
